mapper.select:
select distinct a.SCORETRANSACTION,a.EXAMINETYPE,a.TOPICNAME,max(a.id) as max
from TBL_FWGL_EXAMINE_TOPIC a
where 1=1

    and a.examineType = #{param.examineType}


    and a.BELONGGROUP = #{param.belongGroup}


    and a.CREATOR = #{param.creator}


    and a.WORKUNIT = #{param.workUnit}

group by a.SCORETRANSACTION,a.EXAMINETYPE,a.TOPICNAME
order by max desc
